script:
frappe.ui.form.on("Data Import", {
	import_file(frm) {
		// When import file is set and document is saved
		if (frm.doc.import_file && !frm.is_new()) {
			// Show confirmation dialog for Smart Import
			frappe.confirm(
				__("Use Smart Import? This will analyze the file and insert data automatically without manual mapping."),
				function() {
					// User confirmed - start Smart Import
					frm.call({
						method: "dcnet_apps.utils.smart_import.smart_import",
						args: {
							doctype: frm.doc.reference_doctype,
							file_path: frm.doc.import_file
						},
						callback: function(r) {
							if (r.message) {
								const result = r.message;
								const message = __("Smart Import Complete: {0} records created, {1} failed", [result.success, result.failed]);

								if (result.failed > 0) {
									frappe.msgprint({
										title: __("Import Completed with Errors"),
										message: message + "<br/>" + result.errors.join("<br/>"),
										indicator: "orange"
									});
								} else {
									frappe.show_alert({
										message: message,
										indicator: "green"
									});
								}

								frm.reload_doc();
							}
						},
						error: function(r) {
							frappe.show_alert({
								message: __("Smart Import failed"),
								indicator: "red"
							});
						}
					});
				},
				function() {
					// User declined - use standard import
					frappe.show_alert({
						message: __("Using standard import. Click 'Start Import' button."),
						indicator: "blue"
					});
				}
			);
		}
	}
});
